questions.solution:
function spyOn(object, name) {
  const original = object[name];
  const spy = {
    calls: [],
    restore() {
      object[name] = original;
    },
  };
  object[name] = function (...args) {
    spy.calls.push(args);
    return original.apply(this, args);
  };
  return spy;
}

const calculator = {
  factor: 10,
  scale(n) { return n * this.factor; },
};

const spy = spyOn(calculator, "scale");
console.log(calculator.scale(3), calculator.scale(5), spy.calls);
spy.restore();
calculator.scale(7);
console.log(spy.calls.length);

